<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { apiGet, apiRequest } from '../services/api.js'
import { useAuthStore } from '../stores/auth.js'
import { label, today } from '../utils.js'
import FormPanel from '../components/FormPanel.vue'
import SidePanel from '../components/SidePanel.vue'
import AppIcon from '../components/AppIcon.vue'
import { useWorkspaceStore } from '../stores/workspace.js'
const auth = useAuthStore(), workspace = useWorkspaceStore(), route = useRoute(), router = useRouter()
const companies = computed(() => workspace.companies), company = computed({ get: () => workspace.companyId, set: value => { workspace.companyId = Number(value) } })
const campaigns = ref([]), contents = ref([]), units = ref([]), error = ref(''), notice = ref(''), busy = ref(false), formKey = ref(0), creating = ref(false)
const suffix = () => '?' + new URLSearchParams({ company_id: company.value })
const fields = computed(() => [ { name: 'title', label: 'Nome da campanha', max: 180 }, { name: 'cycle_label', label: 'Ciclo / edição', max: 100, help: 'Ex.: Ciclo 1 · conhecer e acolher' }, { name: 'objective', label: 'Objetivo e convite à participação', type: 'textarea', max: 2000, wide: true }, { name: 'start_date', label: 'Início', type: 'date', default: today() }, { name: 'end_date', label: 'Encerramento', type: 'date' }, { name: 'industry_unit_id', label: 'Unidade industrial', optional: true, options: [{ value: null, label: 'Todas as unidades' }, ...units.value.map(u => ({ value: Number(u.id), label: u.name }))], default: null }, { name: 'audience', label: 'Público elegível', options: [{ value: 'worker', label: 'Trabalhadores' }, { value: 'dependent', label: 'Dependentes' }, { value: 'all', label: 'Trabalhadores e dependentes' }], default: 'all' }, { name: 'content_ids', label: 'Conteúdos publicados deste ciclo', type: 'checkbox_group', wide: true, options: contents.value.filter(c => c.status === 'published').map(c => ({ value: Number(c.id), label: c.title })) } ])
async function load() { const [c, e, o] = await Promise.all([apiGet('/management/campaigns' + suffix()), apiGet('/management/contents' + suffix()), apiGet('/management/overview' + suffix())]); campaigns.value = c; contents.value = e; units.value = o.industry_units }
async function change() { busy.value = true; error.value = ''; formKey.value++; try { await load() } catch (e) { campaigns.value = []; error.value = e.message } finally { busy.value = false } }
async function create(data) { busy.value = true; error.value = ''; try { await apiRequest('/management/campaigns' + suffix(), 'POST', { ...data, industry_unit_id: data.industry_unit_id || null }); await load(); formKey.value++; creating.value = false; router.replace({ path: route.path }); notice.value = 'Ciclo criado como rascunho. Ative quando estiver pronto para convidar o público elegível.' } catch (e) { error.value = e.message } finally { busy.value = false } }
async function status(c, status) { busy.value = true; error.value = ''; try { await apiRequest(`/management/campaigns/${c.id}/status` + suffix(), 'POST', { status, version: Number(c.version) }); await load(); notice.value = status === 'active' ? 'Ciclo ativado. Convites disponíveis dentro da plataforma, sem envio externo de mensagens.' : 'Ciclo encerrado. O histórico foi preservado.' } catch (e) { error.value = e.message } finally { busy.value = false } }
watch(() => route.query.new, value => { if (value === 'campaign') creating.value = true })
onMounted(async () => { busy.value = true; try { await workspace.ensure(auth.user); await load(); creating.value = route.query.new === 'campaign' } catch (e) { error.value = e.message } finally { busy.value = false } })
</script>
<template><p class="eyebrow">CAMPANHAS POR CICLOS</p><div class="page-heading"><h1>Campanhas e ciclos</h1><button class="btn btn-success" :disabled="busy" @click="creating = true"><AppIcon name="plus" :size="18" /> Novo ciclo</button></div><p class="lead">Convites por indústria, unidade e público. A participação não é uma obrigação nem substitui o cuidado individual.</p><label v-if="companies.length > 1" for="campaign-company" class="form-label">Indústria</label><select v-if="companies.length > 1" id="campaign-company" v-model="company" class="form-select mb-4" :disabled="busy" @change="change"><option v-for="c in companies" :key="c.id" :value="c.id">{{ c.name }}</option></select><p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="notice" class="alert alert-success" role="status">{{ notice }}</p><SidePanel :open="creating" title="Criar ciclo de campanha" :busy="busy" @close="creating = false; $router.replace({ path: $route.path })"><p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p class="small text-secondary">Selecione os conteúdos publicados e o público. A ativação será feita após salvar o rascunho.</p><FormPanel :key="`${company}-${formKey}`" :fields="fields" :busy="busy" submit-label="Salvar rascunho do ciclo" @submit="create" /></SidePanel><section><h2 class="h4">Campanhas e resultados agregados</h2><div class="row g-4"><div v-for="c in campaigns" :key="c.id" class="col-lg-6"><article class="card card-body h-100"><p class="eyebrow">{{ c.cycle_label }}</p><h3 class="h5">{{ c.title }}</h3><p>{{ c.objective }}</p><p class="small text-secondary">{{ c.start_date }} a {{ c.end_date }} · {{ label(c.status) }}</p><p v-if="c.suppressed" class="alert alert-light border small">Grupo pequeno: indicadores de participação suprimidos. Nenhum histórico individual de vídeo ou cuidado é enviado à empresa.</p><template v-else><p>Participantes elegíveis convidados: {{ c.participants }}</p><p v-for="s in c.stages" :key="s.stage">{{ label(s.stage) }}: {{ s.count ?? 'Grupo pequeno · suprimido' }}</p></template><div class="d-flex gap-2 mt-auto"><button v-if="c.status !== 'closed'" class="btn btn-success" :disabled="busy" @click="status(c, 'active')">{{ c.status === 'active' ? 'Incluir novos elegíveis' : 'Ativar ciclo' }}</button><button v-if="c.status === 'active'" class="btn btn-outline-secondary" :disabled="busy" @click="status(c, 'closed')">Encerrar ciclo</button></div></article></div></div></section></template>
